#[derive(Parser, Debug)]
#[command(name = "rhit")]
#[command(about = "Analyzes nginx logs", long_about = None)]
pub struct Args {
    /// Files to analyze
    #[arg(value_name = "FILES")]
    pub files: Vec<PathBuf>,

    #[arg(long, short)]
    pub help: bool,

    #[arg(long)]
    pub version: bool,

    /// Color output: auto, yes, or no
    #[arg(long, value_name = "COLOR", default_value = "auto")]
    pub color: String,

    /// Key for sorting/histogram: hits or bytes
    #[arg(long, short, value_name = "KEY", default_value = "hits")]
    pub key: String,

    /// Detail level from 0 to 6
    #[arg(long, short = 'l', value_name = "LENGTH", default_value = "1")]
    pub length: usize,

    /// Fields to display (comma-separated)
    #[arg(long, short = 'f', value_name = "FIELDS")]
    pub fields: Option<String>,

    /// Show changes (recent increases/decreases)
    #[arg(long, short = 'c')]
    pub changes: bool,

    /// Filter by date
    #[arg(long, short = 'd', value_name = "DATE")]
    pub date: Option<String>,

    /// Filter by time
    #[arg(long, short = 't', value_name = "TIME")]
    pub time: Option<String>,

    /// Filter by IP
    #[arg(long, short = 'i', value_name = "IP")]
    pub ip: Option<String>,

    /// Filter by method
    #[arg(long, short = 'm', value_name = "METHOD")]
    pub method: Option<String>,

    /// Filter by path (regex or pattern)
    #[arg(long, short = 'p', value_name = "PATH")]
    pub path: Option<String>,

    /// Filter by referer
    #[arg(long, short = 'r', value_name = "REFERER")]
    pub referer: Option<String>,

    /// Filter by status (can be ranges like 4xx, 400-410)
    #[arg(long, short = 's', value_name = "STATUS")]
    pub status: Option<String>,

    /// Show all paths including resources
    #[arg(long, short = 'a')]
    pub all: bool,

    /// Try to open all files regardless of name
    #[arg(long)]
    pub no_name_check: bool,

    /// Output format: tables, csv, json, or raw
    #[arg(long, short = 'o', value_name = "OUTPUT", default_value = "tables")]
    pub output: String,

    /// Don't print anything during load
    #[arg(long)]
    pub silent_load: bool,
}
EOF

