cat > /workspace/src/log_parser.rs << 'EOF'
use regex::Regex;
use chrono::{NaiveDateTime, NaiveDate};
use std::sync::OnceLock;

#[derive(Debug, Clone)]
pub struct LogEntry {
    pub remote_addr: String,
    pub date: NaiveDate,
    pub time: String,
    pub method: String,
    pub path: String,
    pub status: u16,
    pub bytes_sent: u64,
    pub referer: String,
    pub user_agent: String,
}

fn nginx_regex() -> &'static Regex {
    static REGEX: OnceLock<Regex> = OnceLock::new();
    REGEX.get_or_init(|| {
        Regex::new(
            r#"^(\S+)\s+-\s+-\s+\[([^\]]+)\]\s+"(\w+)\s+(\S+)\s+\S+"\s+(\d+)\s+(\d+)\s+"([^"]*)"\s+"([^"]*)""#
        ).unwrap()
    })
}

pub fn parse_log_line(line: &str) -> Option<LogEntry> {
    let regex = nginx_regex();
    let caps = regex.captures(line)?;

    let remote_addr = caps.get(1)?.as_str().to_string();
    let date_time_str = caps.get(2)?.as_str();
    let method = caps.get(3)?.as_str().to_uppercase();
    let path = caps.get(4)?.as_str().to_string();
    let status: u16 = caps.get(5)?.as_str().parse().ok()?;
    let bytes_sent: u64 = caps.get(6)?.as_str().parse().ok()?;
    let referer = caps.get(7)?.as_str().to_string();
    let user_agent = caps.get(8)?.as_str().to_string();

    // Parse date/time: "29/Apr/2024:12:34:56 +0000"
    let dt_parts: Vec<&str> = date_time_str.split(':').collect();
    if dt_parts.len() != 3 {
        return None;
    }

    let date_part = dt_parts[0];
    let time_part = format!("{}:{}:{}", dt_parts[1], dt_parts[2], 
        date_time_str.split(':').nth(3).unwrap_or("00"));

    let datetime_str = format!("{} {}", date_part, time_part);
    let naive_dt = NaiveDateTime::parse_from_str(&datetime_str, "%d/%b/%Y %H:%M:%S").ok()?;

    Some(LogEntry {
        remote_addr,
        date: naive_dt.date(),
        time: time_part,
        method,
        path,
        status,
        bytes_sent,
        referer,
        user_agent,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_log_line() {
        let line = r#"192.168.1.1 - - [29/Apr/2024:12:34:56 +0000] "GET /index.html HTTP/1.1" 200 1234 "-" "Mozilla/5.0""#;
        let entry = parse_log_line(line).unwrap();
        assert_eq!(entry.remote_addr, "192.168.1.1");
        assert_eq!(entry.method, "GET");
        assert_eq!(entry.path, "/index.html");
        assert_eq!(entry.status, 200);
        assert_eq!(entry.bytes_sent, 1234);
    }
}
EOF

