    let naive_dt = NaiveDateTime::parse_from_str(&datetime_str, "%d/%b/%Y %H:%M:%S").ok()?;

    Some(LogEntry {
        remote_addr,
        date: naive_dt.date(),
        time: time_part,
        method,
