            i + 1, path_display, hits, percent, bytes, width = max_path_len
        );
    }
    println!("└───┴{:─<width$}┴────┴─────┴─────┘", "", width = max_path_len + 2);

    Ok(())
}

pub fn print_csv(entries: &[LogEntry]) -> Result<(), Box<dyn std::error::Error>> {
    println!("date,time,remote address,method,path,status,bytes sent,referer");
    for entry in entries {
        println!(
            "{},{},{},{},\"{}\",{},{},\"{}\"",
            entry.date.format("%Y/%m/%d"),
            entry.time,
            entry.remote_addr,
            entry.method,
            entry.path,
            entry.status,
            entry.bytes_sent,
            entry.referer
        );
    }
    Ok(())
}

pub fn print_json(entries: &[LogEntry]) -> Result<(), Box<dyn std::error::Error>> {
    println!("[");
    for (i, entry) in entries.iter().enumerate() {
        let json_obj = json!({
            "date": entry.date.format("%Y/%m/%d").to_string(),
            "time": entry.time,
            "remote_addr": entry.remote_addr,
            "method": entry.method,
            "path": entry.path,
            "status": entry.status.to_string(),
            "bytes_sent": entry.bytes_sent,
            "referer": entry.referer,
        });
        if i < entries.len() - 1 {
            println!("  {},", json_obj.to_string());
        } else {
            println!("  {}", json_obj.to_string());
        }
    }
    println!("]");
    Ok(())
}

pub fn print_raw(entries: &[LogEntry]) -> Result<(), Box<dyn std::error::Error>> {
    for entry in entries {
        println!(
            "{} - - [{}:00 +0000] \"{} {} HTTP/1.1\" {} {} \"{}\" \"{}\"",
            entry.remote_addr,
            entry.date.format("%d/%b/%Y"),
            entry.method,
            entry.path,
            entry.status,
            entry.bytes_sent,
            entry.referer,
            entry.user_agent
        );
    }
    Ok(())
}

fn is_resource(path: &str) -> bool {
    let extensions = [
        ".js", ".css", ".gif", ".jpg", ".jpeg", ".png", ".ico", ".woff", ".woff2",
        ".ttf", ".svg", ".webp", ".flv", ".swf", ".mp3", ".mp4", ".webm", ".pdf",
    ];
    for ext in &extensions {
        if path.ends_with(ext) {
            return true;
        }
    }
    false
}
