    println!("    -s, --status <STATUS>     Filter by status");
    println!("    -a, --all                 Show all paths");
    println!("    --no-name-check           Check all files");
    println!("    -o, --output <OUTPUT>     Output format: tables, csv, json, raw");
    println!("    --silent-load             Silent loading");
}
