use crate::log_parser::LogEntry;
use crate::date_time::NaiveDate;

pub struct Filters {
    pub date_range: Option<(NaiveDate, NaiveDate)>,
    pub time_range: Option<(String, String)>,
    pub ip: Option<String>,
    pub method: Option<String>,
    pub path: Option<String>,
    pub referer: Option<String>,
    pub status: Option<String>,
}

impl Filters {
    pub fn matches(&self, entry: &LogEntry) -> bool {
        if let Some(ref date_range) = self.date_range {
            if entry.date < date_range.0 || entry.date > date_range.1 {
                return false;
            }
        }

        if let Some(ref status_filter) = self.status {
            if !self.matches_status(entry.status, status_filter) {
                return false;
            }
        }

        if let Some(ref ip_filter) = self.ip {
            if !self.matches_pattern(&entry.remote_addr, ip_filter) {
                return false;
            }
        }

        if let Some(ref method_filter) = self.method {
            if !self.matches_method(&entry.method, method_filter) {
                return false;
            }
        }

        if let Some(ref path_filter) = self.path {
            if !self.matches_path(&entry.path, path_filter) {
                return false;
            }
        }

        if let Some(ref ref_filter) = self.referer {
            if !self.matches_pattern(&entry.referer, ref_filter) {
                return false;
            }
        }

        true
    }

    fn matches_pattern(&self, value: &str, pattern: &str) -> bool {
        if pattern.starts_with('!') {
            !self.matches_pattern(value, &pattern[1..])
        } else {
            value.contains(pattern)
        }
    }

    fn matches_method(&self, method: &str, filter: &str) -> bool {
        if filter.starts_with('!') {
            method != &filter[1..]
        } else if filter == "none" {
            method.is_empty()
        } else if filter == "other" {
            !["GET", "POST", "PUT", "DELETE", "HEAD", "OPTIONS", "PATCH", "CONNECT"].contains(&method)
        } else {
            method == filter
        }
    }

    fn matches_path(&self, path: &str, filter: &str) -> bool {
        if filter.starts_with('!') && filter.len() > 1 {
            !self.matches_path(path, &filter[1..])
        } else if filter.contains(',') {
            filter.split(',').all(|part| self.matches_pattern(path, part.trim()))
        } else {
            self.matches_pattern(path, filter)
        }
    }

    fn matches_status(&self, status: u16, filter: &str) -> bool {
        if filter.starts_with('!') {
            !self.matches_status(status, &filter[1..])
        } else if filter.ends_with("xx") {
            let class = &filter[0..1];
            let status_class = (status / 100).to_string();
            status_class == class
        } else if filter.contains('-') {
            let parts: Vec<&str> = filter.split('-').collect();
            if parts.len() == 2 {
                if let (Ok(start), Ok(end)) = (parts[0].parse::<u16>(), parts[1].parse::<u16>()) {
                    return status >= start && status <= end;
                }
            }
            false
        } else if filter.contains(',') {
            filter.split(',').any(|part| self.matches_status(status, part.trim()))
        } else if let Ok(st) = filter.parse::<u16>() {
            status == st
        } else {
            false
        }
    }
}

impl Default for Filters {
    fn default() -> Self {
        Filters {
            date_range: None,
            time_range: None,
            ip: None,
            method: None,
            path: None,
            referer: None,
            status: None,
        }
    }
}
