use std::io::Write;

pub struct ProgressBar {
    silent: bool,
}

impl ProgressBar {
    pub fn new(silent: bool) -> Self {
        ProgressBar { silent }
    }

    pub fn update(&self, current: usize, total: usize) {
        if self.silent {
            return;
        }

        let percent = if total == 0 { 0 } else { (current * 100) / total };
        let width = 40;
        let filled = (percent * width) / 100;

        let bar = "█".repeat(filled) + &" ".repeat(width.saturating_sub(filled));

        print!("\r\x1b[2K   {} / {} \x1b[48;5;5m\x1b[38;5;11m{}\x1b[49m\x1b[39m", current, total, bar);
        let _ = std::io::stdout().flush();
    }

    pub fn finish(&self) {
        if !self.silent {
            println!("\r\x1b[2K");
        }
    }
}
EOF

