use crate::cli::Args;
use crate::log_parser::{self, LogEntry};
use crate::filters::Filters;
use crate::progress::ProgressBar;
use crate::date_time::NaiveDate;
use std::path::PathBuf;
use std::fs::File;
use std::io::{BufRead, BufReader};

pub struct Analyzer {
    pub entries: Vec<LogEntry>,
    pub filters: Filters,
    pub color: bool,
}

impl Analyzer {
    pub fn new(args: &Args) -> Self {
        let filters = Filters {
            status: args.status.clone(),
            ip: args.ip.clone(),
            method: args.method.clone(),
            path: args.path.clone(),
            referer: args.referer.clone(),
            date_range: None,
            time_range: None,
        };

        let color = args.color == "yes" || (args.color == "auto");

        Analyzer {
            entries: Vec::new(),
            filters,
            color,
        }
    }

    pub fn analyze(&mut self, paths: &[PathBuf]) -> Result<(), Box<dyn std::error::Error>> {
        let progress = ProgressBar::new(false);
        let mut file_count = 0;
        let mut files_to_process = Vec::new();

        // Collect all files
        for path in paths {
            if path.is_file() {
                files_to_process.push(path.clone());
            } else if path.is_dir() {
                if let Ok(entries) = std::fs::read_dir(path) {
                    for entry in entries {
                        if let Ok(entry) = entry {
                            let p = entry.path();
                            if p.is_file() {
                                let name = p.to_string_lossy();
                                if name.ends_with(".log") 
                                    || name.ends_with(".log.gz")
                                    || name.ends_with(".gz")
                                {
                                    files_to_process.push(p);
                                }
                            }
                        }
                    }
                }
            }
        }

        file_count = files_to_process.len();

        for (idx, path) in files_to_process.iter().enumerate() {
            progress.update(idx, file_count);
            let _ = self.load_file(path);
        }

        progress.finish();
        Ok(())
    }

    fn load_file(&mut self, path: &PathBuf) -> Result<(), Box<dyn std::error::Error>> {
        let is_gzip = path.to_string_lossy().ends_with(".gz");

        if is_gzip {
            // Try to decompress gzip
            use std::process::Command;
            let output = Command::new("gunzip")
                .arg("-c")
                .arg(path)
                .output();

            if let Ok(output) = output {
                let content = String::from_utf8_lossy(&output.stdout);
                for line in content.lines() {
                    if let Some(entry) = log_parser::parse_log_line(line) {
                        if self.filters.matches(&entry) {
                            self.entries.push(entry);
                        }
                    }
                }
            }
        } else {
            let file = File::open(path)?;
            let reader = BufReader::new(file);
            for line in reader.lines() {
                if let Ok(line) = line {
                    if let Some(entry) = log_parser::parse_log_line(&line) {
                        if self.filters.matches(&entry) {
                            self.entries.push(entry);
                        }
                    }
                }
            }
        }

        Ok(())
    }

    pub fn print_output(&self, args: &Args) -> Result<(), Box<dyn std::error::Error>> {
        match args.output.as_str() {
            "tables" => crate::output::print_tables(&self.entries, args, self.color)?,
            "csv" => crate::output::print_csv(&self.entries)?,
            "json" => crate::output::print_json(&self.entries)?,
            "raw" => crate::output::print_raw(&self.entries)?,
            _ => println!("Unknown output format: {}", args.output),
        }

        if !args.silent_load {
            if !self.entries.is_empty() {
                let file_count = 1; // simplified
                println!("I've read {} file in {:?}", file_count, "...");
            }
        }
        Ok(())
    }
}
EOF

