use cli::Args;
use log_analyzer::Analyzer;
use std::path::PathBuf;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse_args();

    if args.version {
        println!("rhit {}", env!("CARGO_PKG_VERSION"));
        return Ok(());
    }

    if args.help {
        print_help();
        return Ok(());
    }

    let paths = if args.files.is_empty() {
        vec![PathBuf::from("/var/log/nginx")]
    } else {
        args.files.clone()
    };

    let mut analyzer = Analyzer::new(&args);
    analyzer.analyze(&paths)?;
    analyzer.print_output(&args)?;

    Ok(())
}

