            entry.time,
            entry.remote_addr,
            entry.method,
            entry.path,
            entry.status,
            entry.bytes_sent,
            entry.referer
        );
    }
    Ok(())
}

pub fn print_json(entries: &[LogEntry]) -> Result<(), Box<dyn std::error::Error>> {
    println!("[");
    for (i, entry) in entries.iter().enumerate() {
        println!(
            "  {{\n    \"date\": \"{}\",\n    \"time\": \"{}\",\n    \"remote_addr\": \"{}\",\n    \"method\": \"{}\",\n    \"path\": \"{}\",\n    \"status\": \"{}\",\n    \"bytes_sent\": {},\n    \"referer\": \"{}\"\n  {}",
            entry.date,
            entry.time,
            entry.remote_addr,
            entry.method,
            entry.path,
            entry.status,
            entry.bytes_sent,
            entry.referer,
