use crate::cli::Args;
use crate::log_parser::LogEntry;
use crate::date_time::NaiveDate;
use std::collections::HashMap;

pub fn print_tables(entries: &[LogEntry], args: &Args, _color: bool) -> Result<(), Box<dyn std::error::Error>> {
    if entries.is_empty() {
        println!("No matching log entries");
        return Ok(());
    }

    // Calculate statistics
    let total_hits = entries.len();
    let total_bytes: u64 = entries.iter().map(|e| e.bytes_sent).sum();
    let min_date = entries.iter().map(|e| e.date).min().unwrap();
    let max_date = entries.iter().map(|e| e.date).max().unwrap();

    println!(
        "{} hits and {} from {} to {}",
        total_hits, total_bytes, min_date, max_date
    );

    // Date table
    let mut date_counts: HashMap<NaiveDate, (u64, u64)> = HashMap::new();
    for entry in entries {
        let entry_date = entry.date;
        let (hits, bytes) = date_counts.entry(entry_date).or_insert((0, 0));
        *hits += 1;
        *bytes += entry.bytes_sent;
    }

    let mut dates: Vec<_> = date_counts.iter().collect();
    dates.sort_by_key(|&(d, _)| *d);

    // Find max bytes across all dates for histogram scaling
    let max_bytes = date_counts.values().map(|(_, b)| *b).max().unwrap_or(1);

    println!("┌──────────┬────┬─────┬────────────────────┐");
    println!("│   date   │hits│bytes│0                  {}│", if max_bytes > 0 { (max_bytes / 1000).max(1) } else { 1 });
    println!("├──────────┼────┼─────┼────────────────────┤");
    for (date, (hits, bytes)) in dates {
        let bar_width = if max_bytes > 0 {
            (*bytes as f64 / max_bytes as f64 * 20.0) as usize
        } else {
            0
        };
        let bar = "█".repeat(bar_width);
        println!("│{}│{:>4}│{:>5}│{:<20}│", date, hits, bytes, bar);
    }
    println!("└──────────┴────┴─────┴────────────────────┘");

    // Status table - sort by hits descending, then by status ascending
    let mut status_counts: HashMap<u16, (u64, u64)> = HashMap::new();
    for entry in entries {
        let (hits, bytes) = status_counts.entry(entry.status).or_insert((0, 0));
        *hits += 1;
        *bytes += entry.bytes_sent;
    }

    let mut statuses: Vec<_> = status_counts.iter().collect();
    statuses.sort_by(|a, b| {
        let cmp_hits = b.1.0.cmp(&a.1.0); // descending by hits
        if cmp_hits == std::cmp::Ordering::Equal {
            a.0.cmp(&b.0) // ascending by status code
        } else {
            cmp_hits
        }
    });

    println!("{} HTTP status codes. ", status_counts.len());
    println!("┌───┬──────┬────┬─────┬─────┐");
    println!("│ # │status│hits│  %  │bytes│");
    println!("├───┼──────┼────┼─────┼─────┤");
    for (i, (status, (hits, bytes))) in statuses.iter().enumerate() {
        let percent = *hits as f64 / total_hits as f64 * 100.0;
        println!(
            "│{:>2}│{:>5} │{:>4}│{:>5.1}%│{:>5}│",
            i + 1, status, hits, percent, bytes
        );
    }
    println!("└───┴──────┴────┴─────┴─────┘");

    // Referer table - exclude "-" from the table but count them in totals
    let mut ref_counts: HashMap<String, (u64, u64)> = HashMap::new();
    for entry in entries {
        if entry.referer != "-" {
            let (hits, bytes) = ref_counts.entry(entry.referer.clone()).or_insert((0, 0));
            *hits += 1;
            *bytes += entry.bytes_sent;
        }
    }

    let mut referers: Vec<_> = ref_counts.iter().collect();
    referers.sort_by(|a, b| b.1.0.cmp(&a.1.0)); // Sort by hits descending

    // Count including "-" for proper percentages
    let total_hits_with_ref: u64 = entries.len() as u64;

    let max_ref_len = referers.iter().map(|(r, _)| r.len()).max().unwrap_or(10).max(8).min(25);

    println!("{} referrers. ", referers.len());
    println!("┌───┬{:─<width$}┬────┬─────┬─────┐", "", width = max_ref_len + 2);
    println!("│ # │{:<width$}│hits│  %  │bytes│", "referrer", width = max_ref_len);
    println!("├───┼{:─<width$}┼────┼─────┼─────┤", "", width = max_ref_len + 2);
    for (i, (referer, (hits, bytes))) in referers.iter().enumerate() {
        let percent = *hits as f64 / total_hits_with_ref as f64 * 100.0;
        let ref_display = if referer.len() > max_ref_len {
            format!("{}...", &referer[..max_ref_len.saturating_sub(2)])
        } else {
            referer.to_string()
        };
        println!(
            "│{:>2}│{:<width$}│{:>4}│{:>5.1}%│{:>5}│",
            i + 1, ref_display, hits, percent, bytes, width = max_ref_len
        );
    }
    println!("└───┴{:─<width$}┴────┴─────┴─────┘", "", width = max_ref_len + 2);

    // Path table
    let mut path_counts: HashMap<String, (u64, u64)> = HashMap::new();
    for entry in entries {
        if !args.all && is_resource(&entry.path) {
            continue;
        }
        let (hits, bytes) = path_counts.entry(entry.path.clone()).or_insert((0, 0));
        *hits += 1;
        *bytes += entry.bytes_sent;
    }

    let mut paths: Vec<_> = path_counts.iter().collect();
    paths.sort_by(|a, b| b.1.0.cmp(&a.1.0)); // Sort by hits descending

    let max_path_len = paths.iter().map(|(p, _)| p.len()).max().unwrap_or(10).max(4).min(25);
    let limit = match args.length {
        0 => 3,
        1 => 5,
        2 => 10,
        3 => 20,
        4 => 40,
        5 => 80,
        _ => 200,
    };

    let total_path_hits: u64 = path_counts.values().map(|(h, _)| *h).sum();

    println!(
        "{} paths {}(excluding resources like images, css,",
        path_counts.len(),
        if args.all { "(all) " } else { "" }
    );
    println!("etc.). ");
    println!("┌───┬{:─<width$}┬────┬─────┬─────┐", "", width = max_path_len + 2);
    println!("│ # │{:<width$}│hits│  %  │bytes│", "path", width = max_path_len);
    println!("├───┼{:─<width$}┼────┼─────┼─────┤", "", width = max_path_len + 2);
    for (i, (path, (hits, bytes))) in paths.iter().take(limit).enumerate() {
        let percent = if total_path_hits > 0 { (*hits) as f64 / total_path_hits as f64 * 100.0 } else { 0.0 };
        let path_display = if path.len() > max_path_len {
            format!("{}...", &path[..max_path_len.saturating_sub(2)])
        } else {
            path.to_string()
        };
        println!(
            "│{:>2}│{:<width$}│{:>4}│{:>5.1}%│{:>5}│",
            i + 1, path_display, hits, percent, bytes, width = max_path_len
        );
    }
    println!("└───┴{:─<width$}┴────┴─────┴─────┘", "", width = max_path_len + 2);

    Ok(())
}

