pub fn print_raw(entries: &[LogEntry]) -> Result<(), Box<dyn std::error::Error>> {
    for entry in entries {
        let time_parts: Vec<&str> = entry.time.split(':').collect();
        let time_part = if time_parts.len() >= 2 {
            format!("{}:{}", time_parts[0], time_parts[1])
        } else {
            entry.time.clone()
        };
        println!(
            "{} - - [{}:{}:00 +0000] \"{} {} HTTP/1.1\" {} {} \"{}\" \"{}\"",
            entry.remote_addr,
            entry.date,
            time_part,
            entry.method,
            entry.path,
            entry.status,
            entry.bytes_sent,
            entry.referer,
            entry.user_agent
        );
    }
    Ok(())
}

fn is_resource(path: &str) -> bool {
    let extensions = [
        ".js", ".css", ".gif", ".jpg", ".jpeg", ".png", ".ico", ".woff", ".woff2",
        ".ttf", ".svg", ".webp", ".flv", ".swf", ".mp3", ".mp4", ".webm", ".pdf",
    ];
    for ext in &extensions {
        if path.ends_with(ext) {
            return true;
        }
    }
    false
}
